        if self.PARTIES is not None:
            SITAddPARTIES(builder, PARTIES)
        if self.QUANTITIES is not None:
            SITAddQUANTITIES(builder, QUANTITIES)
        if self.PROVENANCE is not None:
            SITAddPROVENANCE(builder, PROVENANCE)
        SIT = SITEnd(builder)
        return SIT
